#!/usr/bin/env python3
# Install Point #6 — Formal, versioned grading rubrics.
# Run from ~/Cyber_Range_Lab-/backup/backend

from pathlib import Path
import datetime
import py_compile
import re
import subprocess
import sys
import tempfile

ROOT = Path.cwd().resolve()
required = [
    ROOT / "app/api/v1/router.py",
    ROOT / "app/api/v1/endpoints/admin_api.py",
    ROOT / "app/services/gradebook_service.py",
    (ROOT / "../src/App.tsx").resolve(),
    (ROOT / "../src/components/admin/AdminSidebar.tsx").resolve(),
]
missing = [str(path) for path in required if not path.exists()]
if missing:
    print("ERROR: Run this from ~/Cyber_Range_Lab-/backup/backend")
    for item in missing:
        print(" -", item)
    sys.exit(1)

stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")

def backup(path: Path):
    dst = path.with_name(path.name + f".before_point6_{stamp}")
    dst.write_bytes(path.read_bytes())
    print("Backup:", dst)

def write_file(relative: str, content: str):
    path = (ROOT / relative).resolve()
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists():
        backup(path)
    path.write_text(content)
    print("Wrote:", path)

